class Solution {
public:
    int minOperations(int n, int m) {
        const int limit = 10000;
        vector<bool> isPrime(limit, true);
        isPrime[0] = isPrime[1] = false;
        for (int p = 2; p * p < limit; ++p) {
            if (isPrime[p]) {
                for (int multiple = p * p; multiple < limit; multiple += p) {
                    isPrime[multiple] = false;
                }
            }
        }
        if (isPrime[n] || isPrime[m]) return -1;

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        vector<int> dist(limit, 1e9);
        pq.push({n, n});
        dist[n] = n;

        while (!pq.empty()) {
            auto [cost, curr] = pq.top();
            pq.pop();
            if (curr == m) return cost;
            if (cost > dist[curr]) continue;

            string s = to_string(curr);
            for (size_t i = 0; i < s.length(); ++i) {
                int d = s[i] - '0';
                if (d < 9) {
                    string nxtS = s;
                    nxtS[i] = (char)('0' + d + 1);
                    int nxt = stoi(nxtS);
                    if (!isPrime[nxt] && cost + nxt < dist[nxt]) {
                        dist[nxt] = cost + nxt;
                        pq.push({cost + nxt, nxt});
                    }
                }
                if (d > 0 && (i > 0 || d > 1)) {
                    string nxtS = s;
                    nxtS[i] = (char)('0' + d - 1);
                    int nxt = stoi(nxtS);
                    if (!isPrime[nxt] && cost + nxt < dist[nxt]) {
                        dist[nxt] = cost + nxt;
                        pq.push({cost + nxt, nxt});
                    }
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int minOperations(int n, int m) {
        int limit = 10000;
        boolean[] isPrime = new boolean[limit];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int p = 2; p * p < limit; ++p) {
            if (isPrime[p]) {
                for (int multiple = p * p; multiple < limit; multiple += p) {
                    isPrime[multiple] = false;
                }
            }
        }
        if (isPrime[n] || isPrime[m]) return -1;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int[] dist = new int[limit];
        Arrays.fill(dist, Integer.MAX_VALUE);
        pq.offer(new int[]{n, n});
        dist[n] = n;

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int cost = top[0], curr = top[1];
            if (curr == m) return cost;
            if (cost > dist[curr]) continue;

            String s = String.valueOf(curr);
            for (int i = 0; i < s.length(); ++i) {
                int d = s.charAt(i) - '0';
                if (d < 9) {
                    String nxtS = s.substring(0, i) + (d + 1) + s.substring(i + 1);
                    int nxt = Integer.parseInt(nxtS);
                    if (!isPrime[nxt] && cost + nxt < dist[nxt]) {
                        dist[nxt] = cost + nxt;
                        pq.offer(new int[]{cost + nxt, nxt});
                    }
                }
                if (d > 0 && (i > 0 || d > 1)) {
                    String nxtS = s.substring(0, i) + (d - 1) + s.substring(i + 1);
                    int nxt = Integer.parseInt(nxtS);
                    if (!isPrime[nxt] && cost + nxt < dist[nxt]) {
                        dist[nxt] = cost + nxt;
                        pq.offer(new int[]{cost + nxt, nxt});
                    }
                }
            }
        }
        return -1;
    }
}

